package br.edu.oficinacampus.dominio.cadastros;

import br.edu.oficinacampus.dominio.compartilhado.*;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.stream.Stream;
import static org.junit.jupiter.api.Assertions.*;

/** Constrói os agregados diretamente: regras não dependem do JSON da interface. */
class InvariantesCadastrosTest {
    @TestFactory Stream<DynamicTest> invariantesDosAgregados() {
        List<DynamicTest> testes = new ArrayList<>();
        testes.add(DynamicTest.dynamicTest("instrutores: exemplo válido", () -> assertDoesNotThrow(() -> new Instrutor(Controle.novo(Estado.ATIVO), "Ana Ribeiro", "Educadora com experiência em oficinas práticas de tecnologia.", "Programação criativa", "ana@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/nome: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), null, "Educadora com experiência em oficinas práticas de tecnologia.", "Programação criativa", "ana@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/nome: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Educadora com experiência em oficinas práticas de tecnologia.", "Programação criativa", "ana@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/apresentacao: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), "Ana Ribeiro", null, "Programação criativa", "ana@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/apresentacao: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), "Ana Ribeiro", "", "Programação criativa", "ana@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/especialidade: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), "Ana Ribeiro", "Educadora com experiência em oficinas práticas de tecnologia.", null, "ana@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/especialidade: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), "Ana Ribeiro", "Educadora com experiência em oficinas práticas de tecnologia.", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "ana@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/contato: opcional", () -> assertDoesNotThrow(() -> new Instrutor(Controle.novo(Estado.ATIVO), "Ana Ribeiro", "Educadora com experiência em oficinas práticas de tecnologia.", "Programação criativa", null))));
        testes.add(DynamicTest.dynamicTest("instrutores/contato: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), "Ana Ribeiro", "Educadora com experiência em oficinas práticas de tecnologia.", "Programação criativa", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"))));
        testes.add(DynamicTest.dynamicTest("espacos: exemplo válido", () -> assertDoesNotThrow(() -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "Bloco A · sala 204", "Mesas modulares e pontos de energia.", 30))));
        testes.add(DynamicTest.dynamicTest("espacos/nome: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), null, "Bloco A · sala 204", "Mesas modulares e pontos de energia.", 30))));
        testes.add(DynamicTest.dynamicTest("espacos/nome: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Bloco A · sala 204", "Mesas modulares e pontos de energia.", 30))));
        testes.add(DynamicTest.dynamicTest("espacos/localizacao: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", null, "Mesas modulares e pontos de energia.", 30))));
        testes.add(DynamicTest.dynamicTest("espacos/localizacao: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Mesas modulares e pontos de energia.", 30))));
        testes.add(DynamicTest.dynamicTest("espacos/descricao: opcional", () -> assertDoesNotThrow(() -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "Bloco A · sala 204", null, 30))));
        testes.add(DynamicTest.dynamicTest("espacos/descricao: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "Bloco A · sala 204", "", 30))));
        testes.add(DynamicTest.dynamicTest("espacos/capacidade: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "Bloco A · sala 204", "Mesas modulares e pontos de energia.", null))));
        testes.add(DynamicTest.dynamicTest("espacos/capacidade: abaixo do mínimo", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "Bloco A · sala 204", "Mesas modulares e pontos de energia.", 0))));
        testes.add(DynamicTest.dynamicTest("espacos/capacidade: acima do máximo", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "Bloco A · sala 204", "Mesas modulares e pontos de energia.", 1001))));
        testes.add(DynamicTest.dynamicTest("oficinas: exemplo válido", () -> assertDoesNotThrow(() -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/titulo: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), null, "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/titulo: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/apresentacao: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", null, "Presencial", 120, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/apresentacao: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "", "Presencial", 120, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/modalidade: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", null, 120, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/modalidade: opção inválida", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Inexistente", 120, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/duracao: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", null, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/duracao: abaixo do mínimo", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 0, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/duracao: acima do máximo", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 481, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/limite: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, null, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/limite: abaixo do mínimo", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 0, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/limite: acima do máximo", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 1001, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/data: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 20, null, "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/data: data inexistente", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 20, "2026-02-31T10:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/data: formato inválido", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 20, "05/11/2026 14:00", "espacos-0", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/espaco: identidade inválida", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 20, "2026-11-05T14:00", "duas palavras", java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/instrutores: escolha obrigatória", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of()))));
        testes.add(DynamicTest.dynamicTest("oficinas/instrutores: identidade inválida", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("duas palavras")))));
        testes.add(DynamicTest.dynamicTest("oficinas/instrutores: sem repetição", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("oficinas-0", "oficinas-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/espaco: obrigatório fora do online", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 20, "2026-11-05T14:00", null, java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas/espaco: dispensado no online", () -> assertDoesNotThrow(() -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Online", 120, 20, "2026-11-05T14:00", null, java.util.List.of("instrutores-0")))));
        testes.add(DynamicTest.dynamicTest("oficinas: realizada depois do término", () -> {
            Oficina o = new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 90, 20, "2026-09-10T14:00", "espacos-0", java.util.List.of("instrutores-0"));
            assertFalse(o.realizada(java.time.LocalDateTime.parse("2026-09-10T15:29")));
            assertTrue(o.realizada(java.time.LocalDateTime.parse("2026-09-10T15:30")));
        }));
        testes.add(DynamicTest.dynamicTest("oficinas: sobreposição de horários", () -> {
            Oficina a = new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120, 20, "2026-11-05T14:00", "espacos-0", java.util.List.of("instrutores-0"));
            Oficina b = new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 60, 20, "2026-11-05T15:30", "espacos-0", java.util.List.of("instrutores-0"));
            Oficina c = new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 60, 20, "2026-11-05T16:00", "espacos-0", java.util.List.of("instrutores-0"));
            assertTrue(a.sobrepoe(b)); assertTrue(b.sobrepoe(a)); assertFalse(a.sobrepoe(c));
        }));
        return testes.stream();
    }
}
